relationships":[{"id":"rel_ilyan_vesper","source_character_id":"chr_ilyan_voss","target_character_id":"chr_vesper_kael","relationship_type":"rival","description":"Ilyan and Vesper are rival physicians: Ilyan wants to preserve the patients' separate testimony, while Vesper believes his inquiry will endanger the order she maintains."},{"id":"rel_nessa_ilyan","source_character_id":"chr_nessa_orr","target_character_id":"chr_ilyan_voss","relationship_type":"patient and physician","description":"Nessa is Ilyan's patient and tests whether his clinical curiosity can make room for her own account and choices."},{"id":"rel_vesper_nessa","source_character_id":"chr_vesper_kael","target_character_id":"chr_nessa_orr","relationship_type":"guardian","description":"Vesper considers herself Nessa's protector, but her effort to restrict discussion of the dream conflicts with Nessa's need to be heard."}]}
